'use strict';
window.SadhanaReportDocument=({start,end,length,sections})=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sadhana report ${start} to ${end}</title><style>
@page{size:A4 portrait;margin:16mm 12mm}*{box-sizing:border-box}body{font:13px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#243d36;margin:0;background:#f4f5f1}.actions{padding:16px 24px;background:#fff;border-bottom:1px solid #dce2da;position:sticky;top:0;display:flex;gap:16px;align-items:center;flex-wrap:wrap}.actions button{background:#285d4c;color:#fff;border:0;padding:12px 18px;border-radius:6px;font:inherit;cursor:pointer}.actions p{margin:0;font-size:12px;color:#52665a}main{max-width:900px;margin:24px auto;background:#fff;padding:36px}h1{font:32px Georgia,serif;margin:0 0 6px}.dates{font-size:16px}.notes{font-size:11px;color:#52665a;border-bottom:1px solid #dce2da;padding-bottom:16px;margin-bottom:24px}section{margin-top:26px}h2{font-size:19px;margin:0 0 6px}section>p{font-size:11px;color:#52665a;margin:0 0 12px}table{width:100%;border-collapse:collapse;table-layout:fixed;font-size:11px}th,td{text-align:left;padding:8px 7px;border-bottom:1px solid #dce2da;overflow-wrap:anywhere;vertical-align:top}th{background:#edf3ee;font-weight:600}th:first-child{width:7%}th:nth-child(2){width:28%}th:nth-child(3){width:33%}thead{display:table-header-group}tr{break-inside:avoid}h2{break-after:avoid}section>p{break-after:avoid}footer{font-size:10px;color:#52665a;margin-top:24px}@media(max-width:600px){main{padding:18px;margin:12px}table{font-size:10px}th,td{padding:6px 4px}}@media print{body{background:white}main{padding:0;margin:0;max-width:none}.actions{display:none}section+section{break-before:page}th{print-color-adjust:exact;-webkit-print-color-adjust:exact}a{color:inherit}}
</style></head><body><div class="actions"><button id="printReport" type="button">Print / Save as PDF</button><p>Select “Save as PDF” as the destination in your browser’s print window. You can close this tab without changing the dashboard.</p></div><main><header><h1>Sadhana summary</h1><p class="dates">${fmtDate(start)} – ${fmtDate(end)} · ${length} days</p><div class="notes">All listed students are included, regardless of dashboard filters. Rankings show lowest values first.<br>Average daily marks follow the scoring methodology, with every selected date included. Missing or unreadable components earn zero credit; readable components retain their marks. This export policy does not claim that unreported practice did not occur.<br>Defaults: 16 rounds, 60 minutes reading/hearing. Confirmed personal targets are used where set. Waking and sleeping marks follow the methodology time bands.</div></header>${sections.join('')}<footer>Generated from the data and targets loaded in this dashboard tab. Dates are inclusive. Each ranking starts on a new printed page.</footer></main></body></html>`;
